UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW picked up Joey from respite provider and transported him to his uncle''s home, Mr. Murray. Skylar and Makenzie were excited to see their baby brother. TW completed home inspection and kinship home study with the family. TW observed the sleeping arrangements of all children, which were appropriate. All children appeared to be appropriately dressed and clean. Mr. Murray and Ms. Donovan have lock boxes for both their medication and guns. Both lock boxes are kept in their room. They will get their heat, smoke detectors, and carbon monoxide installed. Once installed, TW will complete a re-inspection. </p><p>TW provided Mr. Murray and Ms. Donovan with the letter from respite provider that outlined his daily schedule to help him transition. TW discussed safe sleep with Mr. Murray and Ms. Donovan. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-10-16 13:15:59.042', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-10-16 13:15:59.042', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-10-09 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-10-09 14:30:00.000', endtime='2025-10-09 17:00:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='2:30', progressnotereasontypekey='CM,IASM,ISP,MV,PSC,SC,TSR,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcate