UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>This worker received the FBI and MD criminal clearances back for Richard Murray and Stephanie Donovan. There was no history noted for Mr. Murray. There was a misdemeanor and a felony charge noted for Ms. Donovan from August 2015 in Florida. The charges were for possession of heroin. The disposition for the felony charge stated "dropped". A search through Florida Judiciary records noted the felony charge was dropped to a misdemeanor charge and Ms. Donovan received a fine. Worker, M. Young, noted that Ms. Donovan stated she has been sober since the charge. There have been no concerns of substance use by Ms. Donovan and she has never appeared under the influence when worker has completed home visits. Worker asked Ms. Donovan to complete a random drug test and she agreed.</p><p>The concerns were discussed with Jason Sammons and Roy Brewington. It was agreed to move forward with the kinfirst home study and licensure. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', insertedon='2025-10-16 06:50:12.442', archivedby=NULL, archivedon=NULL, updatedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', updatedon='2025-10-16 07:02:54.553', "timestamp"=NULL, savemode=true, progressnotesubtypeid='87e6906c-93b7-43d3-a906-3411ecb3cf06', contactdate='2025-10-14 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-10-14 14:30:00.000', endtime='2025-10-14 15:00:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:30', progressnotereasontypekey='ASM,SV,SMEE', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false,