SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW met with Ms. Grant and Joseph. Upon arrival, Joseph was being held by Ms. Grant. Ms. Grant states that Joey continues to do well. She states that she has no issues with him and they are getting on a consistent schedule at night. Joey appeared to be appropriately dressed and clean. TW informed Ms. Grant that the Department is extending respite for an additional 30 days. TW informed Ms. Grant that if anything changes, as far as him going to family or being sheltered, TW will inform Ms. Grant. Ms. Grant is okay with Joey staying if he needs to be sheltered. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-10-01 15:05:21.250', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-10-01 15:05:21.250', "timestamp"=NULL, savemode=true, progressnotesubtypeid='f3c40498-cf00-4648-96f0-dbdf562bb6ef', contactdate='2025-09-08 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-09-08 16:30:00.000', endtime='2025-09-08 16:45:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:15', progressnotereasontypekey='CM,MV,SC,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Sherilyn Grant', uploadedfile=NULL, 