SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW met with the family to deliver groceries and for a family visit. Ms. Donovan and Mr. Murray states that the children continue to do well and like their new schools. Both Skylar and Mackenzie appeared to be appropriately dressed, clean and happy. Their sleeping arrangements were appropriate. Mackenzie continues to go to therapy. TW reviewed the service plan with the family. Mr. Murray and Ms. Donovan stated that they are trying to do the child support papers for their re-application for TCA. They stated that they are in need of financial assistance for the children and that Mackenzie''s over night pull ups are becoming expensive. TW stated that when they submit Walmart orders for groceries, they can add the pull ups to the order. Mr. Murray thanked TW. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-10-01 14:43:17.501', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-10-01 14:58:52.769', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-09-24 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-09-24 16:15:00.000', endtime='2025-09-24 16:35:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:20', progressnotereasontypekey='CM,MV,SC,SVP,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=N