SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p><strong>Clinical Supervision:</strong></p><ul><li><p>Skylar and Mackenzie are still residing in Princess Anne, MD with uncle  DSS is helping with groceries.</p></li><li><p>The uncle was denied for TCA and SNAP because of income.</p></li><li><p>Joey is still in respite  paying for daycare  in respite for almost 60 days.</p></li><li><p>Worker is going to get Amber tomorrow, 9/24/25, to try and get her into Chrysalis House.</p></li></ul><p><strong>Update as of 9/24/25:</strong></p><ul><li><p>Worker attempted an unannounced home visit on 9/24/25 to take Ms. Murray to White Flint to sign paperwork for Chrysalis House. No one answered the door. Worker attempted to call Ms. Murray as well. </p></li><li><p>White Flint reported Ms. Murray and Ms. Hoppe are being discharged from treatment because they have not been there in 30 days.</p></li><li><p>Discuss plans for the children with A.D. Two FTDMs have been held.</p></li></ul>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', insertedon='2025-09-25 07:50:15.389', archivedby=NULL, archivedon=NULL, updatedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', updatedon='2025-09-25 07:53:26.751', "timestamp"=NULL, savemode=true, progressnotesubtypeid='87e6906c-93b7-43d3-a906-3411ecb3cf06', contactdate='2025-09-23 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-09-23 09:00:00.000', endtime='2025-09-23 10:00:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='1:0', progressnotereasontypekey='ASM,SV,SMEE', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, 