UPDATE cjams.progressnote
SET progressnotetypeid='8d25a26b-91a1-4423-947e-e451e8eff6b7', title=NULL, description='<p>TW contacted Jessica from White Flint for an update to see if Ms. Murray had completed the application for her to go inpatient to the Chrysalis house. Jessica stated that Ms. Murray has not completed it and has not been to groups in the past 2 weeks. She stated that Ms. Murray told her that she is feeling defeated. Jessica stated that she is waiting for Ms. Murray to decide to want to talk and figure out a plan for her treatment. She stated that she thinks Ms. Murray would benefit greatly from inpatient but has not taken the steps to show that she is ready. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-09-10 12:38:46.317', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-09-10 12:38:46.317', "timestamp"=NULL, savemode=true, progressnotesubtypeid=NULL, contactdate='2025-09-10 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime=NULL, endtime=NULL, instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime=NULL, progressnotereasontypekey='CM', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Jessica- White Flint', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=