UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p><strong>Clinical Supervision:</strong></p><ul><li><p>FTDM scheduled for 8/28/25. Respite for 30 days is coming to an end. A new plan needs to be made for Joey.</p></li><li><p>Discussed mother baby unit with Ms. Murray''s counselor but she does not feel its appropriate because Ms. Murray is still using.</p></li><li><p>Only resource identified was an aunt who smokes in the home and has COPD. Joey has breathing problems already from being around smoke</p></li><li><p>Ms. Murray and Ms. Hoppe still don''t have transportation.</p></li><li><p>There are concerns they are still using.</p></li><li><p>The older two children are still with relatives in Somerset County.</p></li></ul><p><strong>Update as of 8/25/2025:</strong></p><ul><li><p>A.D. is fine with Ms. Murray taking Joey to a mother baby unit as a plan.</p></li></ul><p><strong>Update as of 9/2/25:</strong></p><ul><li><p>FTDM was held on 8/28/2025.</p></li><li><p><span style="color:rgb(34, 34, 34);"><span style="background-color:rgb(255, 255, 255);">There''s no family able to care for Joey. The aunt, Aleisha''s child''s aunt, knows of a couple at her church who may be interested and would love to adopt Joey. Worker her know he isn''t up for adoption. Worker tried calling the friend, Monica Santos, and is waiting to hear back.&nbsp;</span></span></p></li><li><p><span style="color:rgb(34, 34, 34);"><span style="background-color:rgb(255, 255, 255);">Jessica at White Flint stated her recommendation to Chrysalis House will be for Ms. Murray to go 30-45 days in treatment and sober before Joey goes. She states that she does not feel like she is ready or showing effort to care for Joey while in treatment.&nbsp;</span></span></p></li></ul>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', insertedon=