UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW completed an unannounced visit with Ms. Murray and Ms. Hoppe. TW asked if the intake was ever completed. They stated that they did not go due to transportation issues. TW stated that she reached out to them and never received a response. TW stated if TW knew then transportation could have been arranged. TW had them make another appt while TW was there. TW scheduled transportation to their White Flint Recovery intakes. Ms. Murray and Ms. Hoppe admitted to still using. TW stated that their family is struggling financially to take care of their children. TW mentioned the possibility of foster care if they did not get themselves into a substance program. TW stated for them to call MA transportation to see if they can set up rides to these appts as they are important. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-08-21 16:57:46.981', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-08-21 16:57:46.981', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-07-15 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-07-15 16:00:00.000', endtime='2025-07-15 16:25:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:25', progressnotereasontypekey='CM,MV,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodei