UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW met with Mr. Murray. Both children appeared to be safe, appropriately dressed and free of any marks or bruises. TW received a list of groceries from Mr. Murray and stated that they would be ordered for pick up while he waits to apply for SNAP benefits. He states that he has been in contact with a taff member at Pittville school but was unsure of Skylar and Mackenzie bus or school schedules. TW stated that she will work on finding out more information. </p><p></p><p>TW met with Ms. Murray. Joey appeared to be safe, appropriately dressed,  and free of any marks or bruises. Ms. Murray stated that she knows that she originally said she could care for Joey for another month but she does not think she can keep him that long. She stated that her neighbor''s relative would be interested in caring for Joey. TW stated that the plan would have to be made by Joey''s parents. Ms. Murray stated that she would talk to them. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-08-21 16:53:26.483', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-08-21 16:53:26.483', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-07-08 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-07-08 14:00:00.000', endtime='2025-07-08 16:30:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='2:30', progressnotereasontypekey='CM,MV,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, st