UPDATE cjams.progressnote
SET progressnotetypeid='8d25a26b-91a1-4423-947e-e451e8eff6b7', title=NULL, description='<p>TW contacted Jessica at White Flint Recovery to follow up on the progress for IOP for Julia Hoppe and Amber Murray. She stated that they both tested positive this week for THC and cocaine. Their group attendance has not been the best. White Flint was allowing them to do virtual classes, which they were still missing so it is not in person. They attended 3 out of 4 the first week, 1/4 groups last week and all groups this week. TW asked if the Chrysalis house is an option for her, which is an inpatient program for mother and baby. Jessica stated that she feels like she is making progress with Amber in outpatient so it is too soon to tell if inpatient is necesary. She stated that she would look into it. She stated that Amber stated that she messed up and had a death in the family. Jessica stated that she has Julia in groups but she is not her counselor. She stated that Julia has not opened up but has been putting for the effort. She stated that she''s been compliant with group even when Amber isn''t. Jessica stated that she would get Julia''s counselor, Kayla to reach out to me. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-08-21 16:42:19.745', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-08-21 16:42:19.745', "timestamp"=NULL, savemode=true, progressnotesubtypeid=NULL, contactdate='2025-08-21 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime=NULL, endtime=NULL, instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime=NULL, progressnotereasontypeke