UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW completed an unannounced visit with supervisor C. Aley to the home of Amber Murray and Julia Hoppe. TW asked what their plans are. Ms. Murray and Ms. Hoppe stated that they both want to engage in treatment at White Flint. TW had them call to set up intakes while TW was present. They had scheduled intakes for July 7 at 1pm. TW stated that she would reach out to see if they attended them. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-08-21 10:23:42.877', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-08-21 10:23:42.877', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-07-02 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-07-02 14:30:00.000', endtime='2025-07-02 14:45:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:15', progressnotereasontypekey='CM,MV,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname=NULL, uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdicti