SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW met with the family. Joey appeared to be appropriately dressed and free of any marks or bruises. He appeared to be bonded with Nichole. Nichole stated that she has been struggling to pay for daycare and does not think she could afford daycare long term. TW told Nichole that the Dept would help her with daycare until she received her TCA and child care subsidy. Nichole thanked TW. TW observed where Joey sleeps. He sleeps in a pack n play. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-08-21 10:13:56.183', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-08-21 10:14:37.236', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-06-24 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-06-24 16:15:00.000', endtime='2025-06-24 16:30:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:15', progressnotereasontypekey='CM,MV,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname=NULL, uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL,