UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p><strong>Clinical Supervision:</strong></p><ul><li><p>FTDM was concluded. Skylar and Mackenzie will remain with their uncle in Princess Anne, MD.</p></li><li><p>Joey is moving to respite today 8/4  plan with aunt''s neighbors fell through</p></li><li><p>Joey has been enrolled in daycare.</p></li><li><p>Ms. Murray and Ms. Hoppe are going to White Flint for substance use treatment  going consistently.</p></li><li><p>They have been responsive to worker.</p></li><li><p>90 days clean and will reassess allowing the children to go back.</p></li><li><p>Have another FTDM to discuss a plan for Joey because respite care should only be for 30 days.</p></li></ul>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', insertedon='2025-08-08 09:59:16.750', archivedby=NULL, archivedon=NULL, updatedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', updatedon='2025-08-08 09:59:51.044', "timestamp"=NULL, savemode=true, progressnotesubtypeid='87e6906c-93b7-43d3-a906-3411ecb3cf06', contactdate='2025-08-04 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-08-04 09:00:00.000', endtime='2025-08-04 10:00:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='1:0', progressnotereasontypekey='ASM,SV,SMEE', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957