UPDATE cjams.progressnote
SET progressnotetypeid='8d25a26b-91a1-4423-947e-e451e8eff6b7', title=NULL, description='<p>TW received the contact information of Lisa Elliott, who is the great aunt of Joseph Murray. She stated that she has COPD and is an 8 year cancer survivor. Ms. Elliott stated that she is on disability so has limited income. She stated that she would need Nichole''s help to care  for Joey. She would need Nichole to take him to doctor''s appts since she is 62 with health issues. <br><br>TW stated that she would speak to her supervisor. </p><p><br>TW then received a phone call from Nichole stating her aunt''s home smells heavily of smoke and she does not think she would be able to give Joey proper care. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-08-04 16:25:24.561', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-08-04 16:25:24.561', "timestamp"=NULL, savemode=true, progressnotesubtypeid=NULL, contactdate='2025-07-16 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime=NULL, endtime=NULL, instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime=NULL, progressnotereasontypekey='CM,FMC', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Lisa Elliott', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningf