UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>7/23/2025</p><p>TW arrived at 7409 Gumboro Road, Pittsville, MD to pick up Amber Murray and Julia Hoppe for transport to the local department for their 11 am meeting. Both were waiting in the parking lot when TW arrived. Both got in the back seat. TW greeted them; they did the same. TW transported them to the local department. Once at the department, TW called worker Monicia Young to advise her that TW and both Ms. Murray and Ms. Hoppe were on the way inside. She advised TW to have them wait in the lobby. TW advised them that she would be at her desk and to text/call when they are finished. After their meeting, TW received texts from supervisor Courtney Aley, worker Monicia Young and Amber stating that the meeting was over and that Amber and Julia were ready to be transported back home. TW met them both outside by the van and transported them back to their home. Once back at their home, they thanked TW as they got out of the van.</p><p>**A copy of the text threads have been uploaded.</p><p>Chenika Johnson, Family Support Worker II</p><p></p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='d967f732-21f3-4430-8b52-d0953c8bf37a', insertedon='2025-07-28 11:01:15.547', archivedby=NULL, archivedon=NULL, updatedby='d967f732-21f3-4430-8b52-d0953c8bf37a', updatedon='2025-07-28 11:14:35.706', "timestamp"=NULL, savemode=true, progressnotesubtypeid='87e6906c-93b7-43d3-a906-3411ecb3cf06', contactdate='2025-07-23 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-07-23 10:20:00.000', endtime='2025-07-23 12:40:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', tota