UPDATE cjams.progressnote
SET progressnotetypeid='a7d762dd-5fb5-460e-b641-a0c52bf1dd60', title=NULL, description='<p>7/23/2025</p><p>8:48 am - TW texted Amber Murray and Julia Hoppe in a group chat to advise them that TW would be arriving to pick them up between 10:15-10:25 am to transport them to their meeting at the local department. Amber replied to thank TW and to let TW know that they will be outside waiting.</p><p>**A copy of the text thread has been uploaded.</p><p>Chenika Johnson, Family Support Worker II</p><p></p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='d967f732-21f3-4430-8b52-d0953c8bf37a', insertedon='2025-07-28 10:57:09.154', archivedby=NULL, archivedon=NULL, updatedby='d967f732-21f3-4430-8b52-d0953c8bf37a', updatedon='2025-07-28 10:57:09.154', "timestamp"=NULL, savemode=true, progressnotesubtypeid='bce1da6e-84a6-4ae6-8cac-da56b74aa228', contactdate='2025-07-23 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime=NULL, endtime=NULL, instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime=NULL, progressnotereasontypekey='CM', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Chenika Johnson, FSW II', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, toj