UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>This Worker arrived at 7409 Gumboro Road, Pittsville MD for the purpose of picking up Amber Murray and Julia Hoppe and transporting them to White Flint Recovery in  Salisbury. Upon TW arriving at the apartment complex, both ladies were sitting on the sidewalk. They approached TW in the vehicle and greetings were exchanged as they entered the rear passenger seats. Amber stated it was a rough morning and she hates monday''s. During the ride, Amber asked TW what happens on Wednesday 7/23/25, because they are to have the FTDM the same time as they are normally at White Flint.  TW advised her to reach out to her caseworker M. Young for guidance.  Amber also informed TW that she had contacted Medical Assistance Transportation and that they would be providing her rides to White Flint on 7/22/25 &amp; 7/23/25.  Arriving at White Flint, TW advised Amber and Julia that TW had to do a few other work related errands and that TW would return by 1pm and for them to text TW if they finished earlier, to which they agreed.  They exited the vehicle and entered the White Flint facility and TW left the premises. </p><p>12:25pm TW received a text stating "were done" and TW acknowledged with a 10 min ETA at White Flint.  Upon TW''s arrival, Julia and Amber were standing outside waiting. They both entered the vehicle and TW began the transport back to their apartment on Gumboro Road.  During the ride Amber leaned her head back and had her eyes closed for the majority. Julia was interactive on her phone.  Arriving at the apartment complex, they both thanked TW and exited the vehicle and TW then left the premises. </p><p>Bobbi Jo Barrall, Family Support Worker II  </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='cd00474e-5c67-4cf4-a7f3-8805342d04b9', insertedon='2025-07-22 14:03:57.453', archivedby=NULL, archivedon=NULL, updatedby='cd00474e-5c67-4cf4-a7f3-8805342d04b9', updatedon='2025-07-22 14:10:39.671', "timestamp"=NULL, savemode=true, progressnotesubtypeid='c881fa2c-1450-4c8a-b0c5-e27fb4f707e5', contactdate='2025-07-21 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-07-21 10:15:00.000', endtime='2025-07-21 12:50:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='2:35', progressnotereasontypekey='CM,MD,OT,TSR', locationname='Transport: Gumboro Rd & White Flint ', witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Bobbi Jo Barrall', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, tojurisdictionid=NULL, transferdate=NULL, transfertime=NULL, travelstarttime=NULL, travelendtime=NULL, servicesprovided=NULL, otherservices=NULL, anyriskpresented=NULL, otherrisk=NULL, witsid=15188312, focusperson='{"focuspersonjson":[{"participanttypekey":"IP","intakeservicerequestactorid":"c68026f8-8851-45b3-9259-70b5b4e142b7","participantid":"c68026f8-8851-45b3-9259-70b5b4e142b7","firstname":"JULIA","lastname":"HOPPE","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"03785db3-e329-4e0f-8399-54e3408b870e","participantid":"03785db3-e329-4e0f-8399-54e3408b870e","firstname":"Amber","lastname":"Murray","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null}]}', factor1_risk_scale=NULL, factor2_dependent_independent_scale=NULL, factor3_outcome_scale=NULL
WHERE progressnoteid='f0bc9182-b458-4147-97d0-51bd4c93482e';
UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>At the request of caseworker M. Young, TW arrived at 7409 Gumboro Road, Pittsville MD for the purpose of picking up Amber Murray and Julia Hoppe and transporting them to White Flint Recovery Center in Salisbury MD. Upon TW arriving at the apartment complex, 2 females were standing outside and approached TW to confirm of their transport.  TW confirmed and introductions were made as they both entered the rear seat of the state vehicle. During the ride, Julia and Amber talked among themselves. Due to 2 incorrect addresses given, TW arrived with them to White Flint Recovery Services at 11:06am.  The appointments were scheduled for 11-12pm and 12-1pm.  Amber went inside the facility to confirm that they would still be seen and then returned to the vehicle to inform TW.  As Julia was exiting the vehicle, TW confirmed that she would return by 1pm to pick them up for the transport home.  Both ladies were in agreement and TW then left the premises. </p><p>1pm TW sent a text to inform Julia and Amber that TW had returned and was parked outside.  1:11pm they both exited the White Flint facility and approached the state vehicle, where greetings were exchanged as they got inside. As TW was getting onto Rt. 50, Amber asked TW if it was possible to stop by a Food Lion or Dollar General, as she wanted to pick up a few grocery items. TW stated that was fine, as TW did not have another transport immediately scheduled, so it was decided to go to Food Lion on Tilghman Road.  Once at Food Lion, Amber went inside while Julia and TW remained in the vehicle. Amber returned approximate 10 minutes later with 3-4 bags of groceries and 2 packs of soda. During the remainder of the transport back to Gumboro Road, Amber told TW that they had a car but it is currently not running and too costly to repair.  Arriving at the apartment building, both ladies thanked TW as they collected their groceries, said goodbye and exited the vehicle.  TW then left the premises. </p><p>Bobbi Jo Barrall, Family Support Worker II </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='cd00474e-5c67-4cf4-a7f3-8805342d04b9', insertedon='2025-07-22 08:26:07.335', archivedby=NULL, archivedon=NULL, updatedby='cd00474e-5c67-4cf4-a7f3-8805342d04b9', updatedon='2025-07-22 08:36:07.222', "timestamp"=NULL, savemode=true, progressnotesubtypeid='c881fa2c-1450-4c8a-b0c5-e27fb4f707e5', contactdate='2025-07-16 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-07-16 10:30:00.000', endtime='2025-07-16 13:55:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='3:25', progressnotereasontypekey='CM,MD,OT,TSR', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Bobbi Jo Barrall ', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, tojurisdictionid=NULL, transferdate=NULL, transfertime=NULL, travelstarttime=NULL, travelendtime=NULL, servicesprovided=NULL, otherservices=NULL, anyriskpresented=NULL, otherrisk=NULL, witsid=15186688, focusperson='{"focuspersonjson":[{"participanttypekey":"IP","intakeservicerequestactorid":"c68026f8-8851-45b3-9259-70b5b4e142b7","participantid":"