UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW met with the family. Skylar and Mackenzie were appropriately dressed and free of any marks or bruises. Mr. Murray and Ms. Stephanie stated that things continue to go well. They stated that they think Mackenzie and Skylar could benefit from therapy. TW informed them that the kinship letter should be able to assist them with getting them in therapy. Stephanie stated that Mackenzie is set up for summer school TW printed information to assist the family with enrolling the children into Somerset County Public Schools for the Fall. TW stated that the Dept will be ordering the bunk bed and groceries within the next 2 weeks. The family did not need any other assistance at this time. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-07-15 11:22:14.787', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-07-15 11:39:26.815', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-06-25 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-06-25 13:00:00.000', endtime='2025-06-25 13:15:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:15', progressnotereasontypekey='CM,MV,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Stephanie', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, tojurisdictionid=NULL, transferdate=NULL, transfertime=NULL, travelstarttime=NULL, travelendtime=NULL, servicesprovided=NULL, otherservices=NULL, anyriskpresented=NULL, otherrisk=NULL, witsid=15171301, focusperson='{"focuspersonjson":[{"participanttypekey":"IP","intakeservicerequestactorid":"30753efc-681b-488b-8d48-dd3af20b7736","participantid":"30753efc-681b-488b-8d48-dd3af20b7736","firstname":"RICHARD","lastname":"MURRAY","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"302f3235-dc33-4907-98d6-78c81fec16d7","participantid":"302f3235-dc33-4907-98d6-78c81fec16d7","firstname":"SKYLAR","lastname":"MURRAY","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849","participantid":"4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849","firstname":"MACKENZIE","lastname":"ELLIOT","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null}]}', factor1_risk_scale=NULL, factor2_dependent_independent_scale=NULL, factor3_outcome_scale=NULL
