UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>At the request of caseworker M. Young, TW went to Fruitland Walmart and picked up a grocery order and delivered it to 30290 Deal Island Road, Princess Anne MD 21863.  Upon arriving at the residence, TW sent a text  to 443-397-4340 (Stephanie) to notify that TW was on the way.  Text acknowledged.  Upon arriving, Stephanie and a teenage male child exited the home and carried the groceries inside.  TW then left the premises.</p><p>Bobbi Jo Barrall, Family Support Worker II </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='cd00474e-5c67-4cf4-a7f3-8805342d04b9', insertedon='2025-07-09 13:47:03.920', archivedby=NULL, archivedon=NULL, updatedby='cd00474e-5c67-4cf4-a7f3-8805342d04b9', updatedon='2025-07-09 13:51:07.857', "timestamp"=NULL, savemode=true, progressnotesubtypeid='c881fa2c-1450-4c8a-b0c5-e27fb4f707e5', contactdate='2025-07-09 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-07-09 11:50:00.000', endtime='2025-07-09 11:55:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:5', progressnotereasontypekey='OT', locationname='Princess Anne residence', witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Stephanie, Bobbi Jo Barrall', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, i