UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p><strong>Clinical Supervision:</strong></p><ul><li><p>CPS case transfer.</p></li><li><p>Heroin use in the home around the children.</p></li><li><p>Concerns of drug dealing in the home and reports of Ms. Murray selling her baby on the weekends for drugs.</p></li><li><p>Plans were made for the children to be with relatives.</p></li><li><p>Ms. Murray and her wife have not completed substance use evaluations as told to by CPS.</p></li><li><p>The aunt who has the newborn has filed for custody.</p></li><li><p>The uncle who has the other two children needs assistance with food and beds for the children.</p></li><li><p>Discuss kinfirst with A.D.</p></li><li><p>Attempted home visit with Ms. Murray on 7/2.</p></li></ul>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', insertedon='2025-06-27 14:10:09.065', archivedby=NULL, archivedon=NULL, updatedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', updatedon='2025-06-27 14:29:08.717', "timestamp"=NULL, savemode=true, progressnotesubtypeid='87e6906c-93b7-43d3-a906-3411ecb3cf06', contactdate='2025-06-26 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-06-26 14:00:00.000', endtime='2025-06-26 15:00:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='1:0', progressnotereasontypekey='ASM,SV,SMEE', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=