UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p><span style="color:rgb(62, 65, 69);"><span style="background-color:rgb(255, 255, 255);">TW met with Mr. Murray, Mackenzie, Skylar, Stephanie and worker A. Mumma to transition the case and introduce self to the family. Upon arrival, Mackenzie and Skylar were sitting on the couch. They were appropriately dressed and free of any marks or bruises. Worker A. Mumma called maternal aunt,  Ms. Baker on the phone for the meeting. Ms. Baker began stating that she would not be able to care for Mackenzie long term. Worker A. Mumma then asked to speak to Ms. Baker about this later, as the children were in the room. Mr. Murray then sent Skylar and Mackenzie outside to play. TW asked Mr. Murray if he would be willing to care for Mackenzie also. Mr. Murray expressed that he only has 2 bedrooms and no bed for Mackenzie. TW stated that the Dept could buy a bunk bed for the children to share a room. Mr. Murray stated that he is okay with that and okay with Mackenzie living with him. Mr. Murray needs assistance with getting the children enrolled in school in Somerset and applying for benefits for the children. Worker A. Mumma stated that her supervisor is in contact with Somerset regarding the benefits issues. TW reviewed the initial service agreement with Mr. Murray. TW  and A. Mumma spoke to Skylar and Mackenzie about Mackenzie living at Mr. Murray''s and both children stated that they were fine with it. TW scheduled the next visit with Mr. Murray before leaving.</span></span></p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-06-25 12:26:40.917', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-06-25 12:26:40.917', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1