UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW met with Ms. Murray and Joey. Upon arrival, Joey was playing with toys in the floor. Ms. Murray stated that she is concerned that since she doesn''t have representation, she isn''t sure how to subpoena records. TW informed Ms. Murray that at her court hearing, she would have to tell the judge that DSS has been involved for the court to subpoena records. Ms. Murray stated that she followed up with TCA who stated they did not see her application, although she submitted her drug screen. TW checked and told Ms. Murray that her application is in the system and the last note states that they have 30 days to review. Ms. Murray stated that she did find out that once her TCA is approved, she will be able to get child care subsidy. Ms. Murray stated that she saw Amber Murray riding around in a "bad neighborhood" the other day. TW reviewed the customer''s rights and responsibilites and internet safety. Ms. Murray did not have any additional questions or concerns at this time. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-06-25 12:16:24.421', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-06-25 12:16:50.700', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-06-24 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-06-24 16:15:00.000', endtime='2025-06-24 16:52:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:37', progressnotereasontypekey='CM,MV,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname=NULL, uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, tojurisdictionid=NULL, transferdate=NULL, transfertime=NULL, travelstarttime=NULL, travelendtime=NULL, servicesprovided=NULL, otherservices=NULL, anyriskpresented=NULL, otherrisk=NULL, witsid=15126662, focusperson='{"focuspersonjson":[{"participanttypekey":"IP","intakeservicerequestactorid":"3369a4ba-a5bc-44d3-8b1e-23ad14aa762c","participantid":"3369a4ba-a5bc-44d3-8b1e-23ad14aa762c","firstname":"NICHOLE","lastname":"DOUGLAS","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"f726b90a-0517-43ad-9fbd-6aca85c1dae7","participantid":"f726b90a-0517-43ad-9fbd-6aca85c1dae7","firstname":"Joseph","lastname":"Murray","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null}]}', factor1_risk_scale=NULL, factor2_dependent_independent_scale=NULL, factor3_outcome_scale=NULL
