UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>TW met with Ms. Murray, Joey, and worker A. Mumma to transition the case and introduce self to the family. Upon arrival, Joey was being held by Ms. Murray. He was appropriately dressed and free of any marks or bruises. TW observed where Joey sleeps. He sleeps in a pack n play. TW discussed safe sleep with Ms.Murray. TW reviewed the initial service agreement with Ms. Murray. A. Mumma shared that Ms. Murray has filed for custody of Joey, filed for kinship TCA- pending approval and he attends Northwood Early Learning Center. Ms. Murray stated that she is not able to get representation for her custody case due to legal aid stating that they represented Amber Murray in a DUI case. TW explained that LDSS Worker cannot provide legal advice, but will be providing services to the family until her hearings conclude. TW scheduled the next visit with Ms. Murray before leaving. </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', insertedon='2025-06-25 12:12:14.405', archivedby=NULL, archivedon=NULL, updatedby='8180f7f9-62cf-45aa-8953-43bb5c4a2473', updatedon='2025-06-25 12:12:14.405', "timestamp"=NULL, savemode=true, progressnotesubtypeid='6f31a0fc-e8e1-4130-983e-87e5e08a9252', contactdate='2025-06-17 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-06-17 16:15:00.000', endtime='2025-06-17 17:00:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:45', progressnotereasontypekey='CM,CT,IASM,MV,SC,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witssta