UPDATE cjams.progressnote
SET progressnotetypeid='8d25a26b-91a1-4423-947e-e451e8eff6b7', title=NULL, description='<p>This worker spoke with Katie at Cove Recovery and requested urinalysis results for Amber Murray''s urinalysis on 1/9/25. Katie advised Amber was negative for all substances. Worker requested a copy of the results as well as the invoice to pay the bill. Katie advised she would work on it and send info to worker asap. </p><p>Worker also requested urinalysis results from 12/23/24 random urinalysis. Katie reported that Amber tested positive for marijuana, cocaine and alcohol. Results will also be sent to worker of that test. </p><p>Kerry Price, MSW </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='ab7e0e4d-9082-454c-88de-df66a416fcab', insertedon='2025-01-14 13:46:18.437', archivedby=NULL, archivedon=NULL, updatedby='ab7e0e4d-9082-454c-88de-df66a416fcab', updatedon='2025-01-14 13:47:36.213', "timestamp"=NULL, savemode=true, progressnotesubtypeid='87e6906c-93b7-43d3-a906-3411ecb3cf06', contactdate='2025-01-14 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-01-14 10:48:00.000', endtime='2025-01-14 10:50:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:2', progressnotereasontypekey='CM,INF', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Katie @ Cove Recovery', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, tojurisdictionid=NULL, transferdate=NULL, transfertime=NULL, travelstarttime=NULL, travelendtime=NULL, servicesprovided=NULL, otherservices=NULL, anyriskpresented=NULL, otherrisk=NULL, witsid=14736689, focusperson='{"focuspersonjson":[{"participanttypekey":"IP","intakeservicerequestactorid":"03785db3-e329-4e0f-8399-54e3408b870e","participantid":"03785db3-e329-4e0f-8399-54e3408b870e","firstname":"Amber","lastname":"Murray","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null}]}', factor1_risk_scale=NULL, factor2_dependent_independent_scale=NULL, factor3_outcome_scale=NULL
