UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>This worker met with Amber Murray and her family in their home. Makenzie and Julie were eating lunch and Amber was holding Joseph in her arms. Amber called for Skylar to come into the living room to meet with this worker. Skylar was dressed appropriately and appeared to be in good spirits. He said hello to this worker and advised he was glad to be out of school. Worker asked Skylar what he had been doing on his days off from school and he stated he''s been playing his video game and sleeping in. Amber said, and he''s been eating up everything. Skylar said he is a growing boy and he can''t help it that he eats alot. Skylar came and sat by this worker and told worker she has been having fun playing in the snow but is not looking forward to going back to school. Both Skylar and Makenzie told worker they had a good holiday and got what they wanted. Makenzie got her tablet she wanted and Skylar got his Xbox. Makenzie was excited to tell worker about her Elf on the Shelf and how many awesome things he did during the holiday. She also told worker she was excited for her birthday next month. Skylar returned to his bedroom and Amber yelled and asked him if he had taken his medication and he answered yes. This worker asked what he takes medication for and Amber advised Skylar has Epilepsy and has seizures when he doesn''t take his medication so she reminds him daily. She advised Skylar has been having seizures since age 5 and he has to take the medication. She advised he forgot to take his meds and had a seizure a few days before Christmas which was very scary for both of them. She advised he seizes for several minutes before coming back to himself, but they always call the ambulance to make sure he is ok. Both Skylar and Makenzie appeared well card for. </p><p>Amber advised worker that things have been going well and the kids are doing great. Julie advised things would be better once she finds another job as her seasonal position has ended at Kohl''s dept. store. Amber advised she went to Cove Recovery on yesterday for her random urinalysis as worker requested and was negative for all substances. She advised she has been doing good since she''s been home and wants to remain on track to ensure she is able to take care of her children properly. Amber advised Joseph had a pediatrician appt today and will have more lab work due to his abnormal newborn screening. Joseph continues to gain weight and now weighs 9lbs 2oz; eating 3oz every 3hrs; and loves his binky (pacifier). He also likes watching tv when siting in his swing and seems to like Baby Shark music. This worker advised she was glad things are going well for the family and encouraged Amber and Julie to keep up the good work and support one another. Worker advised Amber that she needs to remain clean/drug free in order to care for her children properly and give them the life they deserve. Worker advised Amber and Julie of the negative effects a parents drug use can have on children. Amber advised she plans to remain clean for her own health and because she wants more in life. This worker asked Julie if she has any children of her own and she saif, only Joseph. This worker reminded her of her bonus children, Skylar and Makenzie, since she and Amber are a couple. Julie said, yes they are mine too. </p><p>This worker reminded Amber and Julie of safe sleep and that there is to be no co-bedding with Joseph. Also that no one should be using marijuana in his presence due to the increased risk of SIDS. Despite the couple stating no one smokes in the home, it reeked of cigarette smoke, so worker also advised them of the risk of second hand smoke on the children and encouraged them to smoke outside the home. Worker discussed case closure with Amber and completed the Aftercare Plan with her as well as reviewed the POSC. Amber agreed to the terms and advised she would do what she has to do to ensure her children are taken care of. Worker advised she needs to be clean and sober to do so and encouraged her to seek treatment if she relapses again as it will offer her the supports she needs to remain clean. Amber advised she would reach out to Cove Recovery again if she needs to. Worker asked if there were any additional service needs of the family and Amber and Julie answered no. </p><p>This worker advised Amber the case will be closed and that she will receive a closing letter in the mail along with a copy of her Aftercare Plan so she is reminded of what she needs to do to maintain her progress. Worker observed Joseph, Skylar and Makenzie to appear safe in their mother and Julie''s care. No injuries visible on either of the children. </p><p>The home appeared neat, clean and organized and met minimal standards. </p><p>Kerry Price, MSW </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='ab7e0e4d-9082-454c-88de-df66a416fcab', insertedon='2025-01-14 11:50:52.620', archivedby=NULL, archivedon=NULL, updatedby='ab7e0e4d-9082-454c-88de-df66a416fcab', updatedon='2025-01-14 12:24:56.004', "timestamp"=NULL, savemode=true, progressnotesubtypeid='f3c40498-cf00-4648-96f0-dbdf562bb6ef', contactdate='2025-01-10 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-01-10 11:20:00.000', endtime='2025-01-10 12:00:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:40', progressnotereasontypekey='CM,CMT,INF,MV,SC,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname=NULL, uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, tojurisdictionid=NULL, transferdate=NULL, transfertime=NULL, travelstarttime=NULL, travelendtime=NULL, servicesprovided=NULL, otherservices=NULL, anyriskpresented=NULL, otherrisk=NULL, witsid=14735988, focusperson='{"focuspersonjson":[{"participanttypekey":"IP","intakeservicerequestactorid":"03785db3-e329-4e0f-8399-54e3408b870e","participantid":"03785db3-e329-4e0f-8399-54e3408b870e","firstname":"Amber","lastname":"Murray","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"302f3235-dc33-4907-98d6-78c81fec16d7","participantid":"302f3235-dc33-4907-98d6-78c81fec16d7","firstname":"SKYLAR","lastname":"MURRAY","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849","participantid":"4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849","firstname":"MACKENZIE","lastname":"ELLIOT","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"f726b90a-0517-43ad-9fbd-6aca85c1dae7","participantid":"f726b90a-0517-43ad-9fbd-6aca85c1dae7","firstname":"Joseph","lastname":"Murray","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null}]}', factor1_risk_scale=NULL, factor2_dependent_independent_scale=NULL, factor3_outcome_scale=NULL
