UPDATE cjams.progressnote
SET progressnotetypeid='070e4f03-4019-4a60-a955-01b9896f167b', title=NULL, description='<p><strong>Clinical Supervision: SEN Assessment</strong></p><p><strong>Referral:</strong> <span style="color:rgb(51, 51, 51);"><span style="background-color:rgb(255, 255, 255);">RS is calling to report a SENs. Mom- Amber Murray 3/6/92. 7409 Gumboro Rd Pittsville, MD. 443-669-8558. Baby: Joseph Murray 12/14/24. Father- not listed. ABGARS 8 &amp; 9. Joseph tested positive for marijuana and cocaine. No with draw symptoms. Mom and baby were discharged on 12/16/24. No complications. Joseph was born at 40.4 weeks vaginal. 6.5 pounds. Mom reports using marijuana 1 month ago and reports she hasn''t used cocaine in years. Mom was presumptive positive for marijuana and cocaine. Mom reports having a medical marijuana card. Mom reports having everything she needs. Pediatrician is Dr. Cooper with CHC.</span></span></p><ul><li><p>Meconium was positive for THC and cocaine mom was presumptive positive for marijuana and cocaine.</p></li><li><p>Denied using cocaine in years stated she was still using marijuana and felt off went to the hospital and found out she was positive for cocaine. Stated the marijuana was laced. Worker reiterated the importance of maintaining a drug free environment at all times.</p></li><li><p>Worker sent mom for a random twice was compliant with this. Test results were negative.</p></li><li><p>Chesapeake Pediatrics is the pediatrician - no medical concerns noted.</p></li><li><p>Older son has epilepsy mom is on top of his treatment.</p></li><li><p>Mom does not work girlfriend was working a seasonal job at Kohls.</p></li><li><p>Family resides in subsidized housing gets child support, WIC, MA, TCA, and SNAP benefits.</p></li><li><p>Safe sleep has been discussed and arrangements have been observed bassinet and pack-n-play. The safe sleep brochure was provided and the acknowledgement form was signed.</p></li><li><p>Birth to Five referral was made.</p></li><li><p>Home is clean and appropriate.</p></li><li><p>No safety concerns have been noted.</p></li><li><p>Case will close.</p></li></ul>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', insertedon='2025-01-13 14:01:54.032', archivedby=NULL, archivedon=NULL, updatedby='857bc591-61f8-4ca8-9d20-7aa3b22cc3d8', updatedon='2025-01-13 14:11:05.168', "timestamp"=NULL, savemode=true, progressnotesubtypeid='87e6906c-93b7-43d3-a906-3411ecb3cf06', contactdate='2025-01-13 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2025-01-13 11:00:00.000', endtime='2025-01-13 12:00:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='1:0', progressnotereasontypekey='ASM,CC,SV,SMEE', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname='Kerry Price', uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, tojurisdictionid=NULL, transferdate=NULL, transfertime=NULL, travelstarttime=NULL, travelendtime=NULL, servicesprovided=NULL, otherservices=NULL, anyriskpresented=NULL, otherrisk=NULL, witsid=14733378, focusperson='{"focuspersonjson":[{"participanttypekey":"IP","intakeservicerequestactorid":"a34e2540-cfd0-4db3-a57e-3b0444b2c8f5","participantid":"a34