UPDATE cjams.progressnote
SET progressnotetypeid='786495b2-c779-4cc4-b812-6a8439bfa96e', title=NULL, description='<p>This worker met with Amber Murray and her three children in their home. This worker entered the home and found it to be neat and organized; met minimal standards. Joseph was sleeping in his swing; dressed in a one piece outfit; and appeared clean and well cared for. Makenzie was sitting in the living room watching cartoons. She appeared to be in good spirits; clean and well cared for; and dressed appropriately. Skylar was still asleep in his bedroom. Amber advised Joseph''s next pediatrician appt is scheduled for 12/26/24. </p><p>Amber advised she went to Cove Recovery to have complete her urinalysis this morning as worker requested. She advised Julie had to go to work today so she had to go get her urinalysis completed before she went. Amber advised she also completed her Change Form and turned it in to have her son added to her food stamp benefits. She also advised she received her WIC benefits on last Friday and picked up formula for Joseph at the grocery store. Joseph weighed 7lbs 7oz at his WIC appt. So he is gaining weight already. Amber advised Joseph continues to do well and she has learned that he doesn''t like to have dirty diapers left on him for too long. </p><p>This worker spoke with Makenzie, who advised she felt safe in her mother''s care. She advised she is a 4th grader at Pittsville ES/Middle School and likes school. She told this worker she doesn''t like her brother because he never wants to play with her. She likes having her baby brother around and holding him. This worker attempted to speak with Skylar but he was still in bed. Skylar appeared well cared for and very tall for his age. Amber advised Skylars is in the 7th grade; 6ft tall; wears a size 13 shoe; and has a very healthy appetite. Worker observed Makenzie, Skylar, and Joseph to appear well cared for and safe in their mother''s care. </p><p>This worker advised Amber that support worker Makara will be visiting the family next week while this worker is on leave. Amber advised that would be fine. </p><p>Kerry Price, MSW </p>', entitytype='servicecase', entitytypeid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', pagetitle=NULL, pageurl=NULL, islatest=NULL, versionof=NULL, insertedby='ab7e0e4d-9082-454c-88de-df66a416fcab', insertedon='2024-12-25 15:23:55.462', archivedby=NULL, archivedon=NULL, updatedby='ab7e0e4d-9082-454c-88de-df66a416fcab', updatedon='2024-12-25 15:54:38.431', "timestamp"=NULL, savemode=true, progressnotesubtypeid='f3c40498-cf00-4648-96f0-dbdf562bb6ef', contactdate='2024-12-23 00:00:00.000', contactname=NULL, progressnotetypekey=NULL, contactroletypekey=NULL, contactphone=NULL, contactemail=NULL, attemptindicator=false, activeflag=1, documentpropertiesid=NULL, starttime='2024-12-23 11:15:00.000', endtime='2024-12-23 11:35:00.000', instantresults=1, contactstatus=true, drugscreen=false, progressnotepurposetypekey=NULL, old_id=NULL, traveltime='', totaltime='0:20', progressnotereasontypekey='ASM,CM,CMT,MV,SC,WV', locationname=NULL, witsinboundid=NULL, roletypekey=NULL, islocked=false, stafftypekey='1', notesid=NULL, witsstatus=NULL, witsupdatedate=NULL, witsupdatebyidno=NULL, contactcategoryidno=NULL, iconimgtext=NULL, parametercodeidno=NULL, detaillookup=NULL, fk_id=NULL, initiationindicator=true, intakeserviceid=NULL, servicecaseid='a005cdd3-55ac-4957-96a6-f3db60e87ad1', isintake='N', otherpersonname=NULL, uploadedfile=NULL, adjustmentfostercaretext=NULL, screeningfortheservicetext=NULL, ischildgotoshool=NULL, qualityofcaretochildtext=NULL, fk_user_id=NULL, etl_userid=NULL, etl_load_date=NULL, fromjurisdictionid=NULL, tojurisdictionid=NULL, transferdate=NULL, transfertime=NULL, travelstarttime=NULL, travelendtime=NULL, servicesprovided=NULL, otherservices=NULL, anyriskpresented=NULL, otherrisk=NULL, witsid=14700165, focusperson='{"focuspersonjson":[{"participanttypekey":"IP","intakeservicerequestactorid":"03785db3-e329-4e0f-8399-54e3408b870e","participantid":"03785db3-e329-4e0f-8399-54e3408b870e","firstname":"Amber","lastname":"Murray","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"302f3235-dc33-4907-98d6-78c81fec16d7","participantid":"302f3235-dc33-4907-98d6-78c81fec16d7","firstname":"SKYLAR","lastname":"MURRAY","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849","participantid":"4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849","firstname":"MACKENZIE","lastname":"ELLIOT","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null},{"participanttypekey":"IP","intakeservicerequestactorid":"f726b90a-0517-43ad-9fbd-6aca85c1dae7","participantid":"f726b90a-0517-43ad-9fbd-6aca85c1dae7","firstname":"Joseph","lastname":"Murray","address1":null,"address2":null,"city":null,"state":null,"zipcode":null,"email":null,"phonenumber":null}]}', factor1_risk_scale=NULL, factor2_dependent_independent_scale=NULL, factor3_outcome_scale=NULL
