UPDATE progressnote
SET focusperson = jsonb_set(
    focusperson::jsonb, 
    '{focuspersonjson}', 
    (
        SELECT jsonb_agg(
            CASE 
                -- Check if intakeservicerequestactorid or participantid matches the old value
                WHEN elem->>'intakeservicerequestactorid' = '4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849'
                     OR elem->>'participantid' = '4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849'
                THEN 
                    -- Replace with new values for both intakeservicerequestactorid and participantid
                    jsonb_set(
                        jsonb_set(
                            elem, 
                            '{intakeservicerequestactorid}', 
                            '"d4d48958-3d5c-4dd4-9d60-178c1d066e08"', 
                            false
                        ),
                        '{participantid}', 
                        '"d4d48958-3d5c-4dd4-9d60-178c1d066e08"', 
                        false
                    )
                ELSE elem
            END
        )
        FROM jsonb_array_elements(focusperson::jsonb->'focuspersonjson') AS elem
    )
),
updatedby = 'CJAMS-62710',
updatedon = now()
WHERE servicecaseid = 'a005cdd3-55ac-4957-96a6-f3db60e87ad1'
  AND activeflag = 1
  AND (
      focusperson::jsonb->'focuspersonjson' @> '[{"intakeservicerequestactorid": "4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849"}]'::jsonb
      OR focusperson::jsonb->'focuspersonjson' @> '[{"participantid": "4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849"}]'::jsonb
  );
 
