where servicecaseid = 'a005cdd3-55ac-4957-96a6-f3db60e87ad1'
  AND activeflag = 1
  AND focusperson::text LIKE '%MACKENZIE%'
  AND focusperson::text LIKE '%ELLIOT%';

	 
