UPDATE assessment
SET submissiondata = REPLACE(
                         REPLACE(
                             regexp_replace(
                                 REPLACE(submissiondata::text, 'MACKENZIE', 'MAKENZIE'),
                                 '\mELLIOT\M', 'ELLIOTT', 'gi'
                             ),
                             '75ebef60-aab2-42e4-9b5a-1b8223f478e2', 'f254401b-8678-4543-8b0b-e8705075a422'
                         ),
                         '4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849', 'd4d48958-3d5c-4dd4-9d60-178c1d066e08'
                     )::jsonb,
    --updatedby = 'CJAMS-62710',
    updatedon = now()
WHERE assessmentid = 'a33be27e-66db-45e9-b792-1037c8531344'
  AND activeflag = 1
  AND (
        submissiondata::text LIKE '%MACKENZIE%'
     OR submissiondata::text ~* '\mELLIOT\M'
     OR submissiondata::text LIKE '%75ebef60-aab2-42e4-9b5a-1b8223f478e2%'
     OR submissiondata::text LIKE '%4b1bd61a-5d5f-4076-8cea-5cfbe1a2f849%'
  );
  
