                   '\mELLIOT\M', 'ELLIOTT', 'gi'
               )::jsonb,
    updatedby = 'CJAMS-62710',
    updatedon = now()
WHERE (datavalue::text ~* 'MACKENZIE'
       OR datavalue::text ~* '\mELLIOT\M')
  AND assessmentsubmissionid = '261104b3-9718-4d41-9959-b860a66f7574'
  AND activeflag = 1;
 
