-- only needed inside the comment.
UPDATE assessmentsubmission
SET datavalue = jsonb_set(
                   datavalue::jsonb,
                   '{CommentstoSupportRating3}',
                   to_jsonb(
                     regexp_replace(
                       regexp_replace(
                         (datavalue::jsonb->>'CommentstoSupportRating3'), 
                         'MACKENZIE', 'MAKENZIE', 'gi'
                       ),
                       'ELLIOT', 'ELLIOTT', 'gi'
                     )
                   ),
                   false
                 ),
    updatedby = 'CJAMS-62710',
    updatedon = now()
WHERE (
      (datavalue::jsonb->>'CommentstoSupportRating3') ~* 'MACKENZIE'
      OR (datavalue::jsonb->>'CommentstoSupportRating3') ~* 'ELLIOT'
      )
  AND assessmentsubmissionid = 'e7e252ad-71cf-4097-8d40-ce2a805cb557'
  AND activeflag = 1;

 
UPDATE submissioncollection
SET datavalue = 'MAKENZIE ELLIOTT',
    updatedby = 'CJAMS-62710',
    updatedon = now()
WHERE submissioncollectionid = 'a8f098fc-ed2d-4bc4-8e46-2253e7ba9450'
  AND activeflag = 1;


/* TYPE AND EXTENT OF CURRENT MALTREATMENT INVESTIGATION: comment
datavalue: The Local Department completed an assessment based on reports of Mackenzie Elliott born exposed to Marijuana. Ms. Murray admitted she used Marijuana socially during the final trimester of pregnancy. Ms. Murray was not required to complete substance abuse treatment and appears to have the ability to provide ongoing safe care.
*/
UPDATE submissioncollection
SET datavalue = regexp_replace(datavalue, 'mackenzie', 'Makenzie', 'gi'),
	updatedby = 'CJAMS-62710',
	updatedon = now()
WHERE assessmentsubmissionid = '78ac9778-9977-452f-bf9a-0122eeeb60af'
  AND submissioncollectionid = 'c78028de-5046-40ba-9e5a-238f2a2a025e'
  AND activeflag = 1;

